    [Theory]
    [MemberData(nameof(FileControls))]
    public void FileReadsWritesAndAppendPreservePythonBytes(string name, string source, string expected, string seedHex, string finalSourceHex, string? finalOutputHex)
    {
        _ = name;
        var host = new MockLythonHost();
        host.SeedBytes("/source.bin", Convert.FromHexString(seedHex));
        var result = new LythonEngine().Run(source, host);
        Assert.True(result.Success, result.Failure?.Message);
        Assert.Equal(expected, result.StandardOutput);
        Assert.Equal(Convert.FromHexString(finalSourceHex), host.ReadBytes("/source.bin"));
        if (finalOutputHex is not null) Assert.Equal(Convert.FromHexString(finalOutputHex), host.ReadBytes("/output.bin"));
    }

    [Theory]
    [MemberData(nameof(FileControls))]
    public async Task FileOperationsActuallySuspend(string name, string source, string expected, string seedHex, string finalSourceHex, string? finalOutputHex)
    {
        _ = name;
        var host = new DelayedLythonHost();
        host.SeedBytes("/source.bin", Convert.FromHexString(seedHex));
        var result = await new LythonEngine().RunAsync(source, host);
        Assert.True(result.Success, result.Failure?.Message);
        Assert.Equal(expected, result.StandardOutput);
        Assert.Equal(Convert.FromHexString(finalSourceHex), host.ReadBytes("/source.bin"));
        if (finalOutputHex is not null) Assert.Equal(Convert.FromHexString(finalOutputHex), host.ReadBytes("/output.bin"));
        Assert.True(host.CompletedAsynchronously > 0);
    }
}
